use serde_json::Value;

pub fn solve(input: Value) -> Value {
    let num = input.as_u64().unwrap();
    let mut count = 0;
    let mut n = num;
    while n > 0 {
        count += n & 1;
        n >>= 1;
    }
    Value::from(count)
}
